const chunks = $input.first().json.chunks;

const documents = chunks.map(c => c.content);

return [{ json: { documents } }];

// Why Code: Filtra, classifica por faixa de confiança, anexa metadados completos e preserva a ordem sequencial de passos (chunk_index) por documento sem perder o ranking de relevância.
const results = $input.first().json.results ?? [];
const chunks = $('Setup chunks').first().json.chunks ?? [];
const settings = $('Settings').first().json;
const minScore = settings.min_score_to_rank ?? 0.50;
const highConfidenceScore = settings.high_confidence_score ?? 0.75;

const approved = results
  .filter(r => r.relevance_score >= minScore && chunks[r.index])
  .map(r => {
    const chunk = chunks[r.index];
    const meta = chunk.metadata ?? {};
    const score = Number(r.relevance_score.toFixed(4));
    const confidence = r.relevance_score >= highConfidenceScore ? 'ALTA' : 'MEDIA';
    const metadata = {
      ...meta,
      doc_id: meta.doc_id ?? chunk.doc_id ?? null,
      file_name: meta.file_name ?? meta.fileName ?? chunk.file_name ?? null,
      chunk_index: Number(meta.chunk_index ?? meta.chunkIndex ?? chunk.chunk_index ?? 0),
      chunk_total: meta.chunk_total ?? meta.chunkTotal ?? chunk.chunk_total ?? null
    };
    return {
      content: chunk.content,
      score,
      confidence,
      metadata,
      formatted: `[${confidence} | score: ${r.relevance_score.toFixed(2)} | doc: ${metadata.file_name ?? metadata.doc_id ?? 'unknown'} | passo: ${metadata.chunk_index + 1}/${metadata.chunk_total ?? '?'}] ${chunk.content}`
    };
  });

if (approved.length === 0) {
  return [{
    json: {
      hasResults: false,
      sortedDocuments: []
    }
  }];
}

const docMaxScore = new Map();
for (const item of approved) {
  const docId = String(item.metadata.doc_id ?? '');
  const currentMax = docMaxScore.get(docId) ?? -Infinity;
  if (item.score > currentMax) {
    docMaxScore.set(docId, item.score);
  }
}

const sortedDocuments = approved.sort((a, b) => {
  const docA = String(a.metadata.doc_id ?? '');
  const docB = String(b.metadata.doc_id ?? '');
  if (docA !== docB) {
    const maxDiff = (docMaxScore.get(docB) ?? 0) - (docMaxScore.get(docA) ?? 0);
    if (maxDiff !== 0) return maxDiff;
    return docA.localeCompare(docB);
  }
  return (a.metadata.chunk_index ?? 0) - (b.metadata.chunk_index ?? 0);
});

return [{
  json: {
    hasResults: true,
    sortedDocuments
  }
}];

const items = $input.all();
const settings = $('Settings').first().json;
const topK = settings.top_k ?? 5;
const minScore = settings.min_score_to_expand ?? 0;
const hits = items.map(item => item.json);

const seen = new Set();
const toFetch = hits
  .sort((a, b) => (b.rrf_score ?? 0) - (a.rrf_score ?? 0))
  .filter(hit => (hit.rrf_score ?? 0) >= minScore)
  .slice(0, topK)
  .map(hit => ({
    doc_id: hit.metadata.doc_id,
    chunk_index: hit.metadata.chunk_index,
    rrf_score: hit.rrf_score ?? 0
  }))
  .filter(f => {
    const key = `${f.doc_id}_${f.chunk_index}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

return [{ json: { hits, toFetch } }];

// Why Code: Deduplica chunks vindos da busca híbrida e da expansão de janela e ordena posicionalmente por doc_id e chunk_index.
const hits = $('Generate List do Context Expansion').first().json.hits ?? [];
const expanded = $input.all().map(i => i.json).filter(c => c && (c.content || c.metadata));

const all = [...hits, ...expanded];

const seen = new Set();
const chunks = all
  .filter(c => {
    const docId = c.metadata?.doc_id ?? c.doc_id;
    const chunkIndex = c.metadata?.chunk_index ?? c.chunk_index;
    if (docId === undefined && chunkIndex === undefined) return false;
    const key = `${docId}_${chunkIndex}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  })
  .sort((a, b) => {
    const docA = String(a.metadata?.doc_id ?? a.doc_id ?? '');
    const docB = String(b.metadata?.doc_id ?? b.doc_id ?? '');
    if (docA !== docB) return docA.localeCompare(docB);
    const idxA = Number(a.metadata?.chunk_index ?? a.chunk_index ?? 0);
    const idxB = Number(b.metadata?.chunk_index ?? b.chunk_index ?? 0);
    return idxA - idxB;
  });

return [{ json: { chunks } }];
